import{P as _v,R as gl,c as El,m as Ms,q as sw}from"./main-RU463FNB.js";var o=class a{static ɵfac=function(i){return new(i||a)};static ɵcmp=gl({type:a,selectors:[[`app-network-guide`]],decls:217,vars:0,consts:[[1,`page`],[`routerLink`,`/`],[1,`eyebrow`],[`id`,`speed`],[`aria-hidden`,`true`,1,`material-symbols-rounded`],[`id`,`latency`],[`id`,`jitter`],[`id`,`tcp-retransmission`],[`id`,`dual-stack`],[`id`,`webrtc`],[`id`,`network-intelligence`]],template:function(i,l){i&1&&(Ms(0,`main`,0)(1,`a`,1),sw(2,`← Dashboard`),El(),Ms(3,`p`,2),sw(4,`Network Guide`),El(),Ms(5,`h1`),sw(6,`Understand your connection`),El(),Ms(7,`p`),sw(8,`Plain-language help for the measurements and network details shown by PingMetric.`),El(),Ms(9,`section`,3)(10,`h2`)(11,`span`,4),sw(12,`speed`),El(),sw(13,` Mbps vs MB/s`),El(),Ms(14,`p`)(15,`b`),sw(16,`b`),El(),sw(17,` means bit; `),Ms(18,`b`),sw(19,`B`),El(),sw(20,` means byte. Eight bits equal one byte. ISPs normally advertise Mbps, while download tools often use MB/s. They describe the same throughput in different units. `),El(),Ms(21,`p`)(22,`code`),sw(23,`MB/s = Mbps / 8`),El(),sw(24,` · `),Ms(25,`code`),sw(26,`Mbps = MB/s × 8`),El()(),Ms(27,`p`),sw(28,` 8 Mbps ≈ 1 MB/s; 40 ≈ 5; 80 ≈ 10; 100 ≈ 12.5; 1,000 ≈ 125. Real downloads can be lower because of Wi-Fi, overhead, congestion, server limits, devices, and other traffic. `),El()(),Ms(29,`section`)(30,`h2`)(31,`span`,4),sw(32,`download`),El(),sw(33,` Download and upload `),El(),Ms(34,`p`),sw(35,` Download is data arriving at your device: websites, streaming and app or cloud downloads. Upload is data leaving it: video calls, backups, file uploads and live streaming. `),El(),Ms(36,`p`)(37,`strong`),sw(38,`M-Lab`),El(),sw(39,` means Measurement Lab, a research project that provides open Internet measurement tools. PingMetric uses its NDT7 service for the dashboard's active download and upload test; the result describes the tested path at that moment, not a guaranteed plan speed. `),El(),Ms(40,`p`)(41,`strong`),sw(42,`NDT7`),El(),sw(43,` is Network Diagnostic Tool version 7. It transfers test data between your browser and an M-Lab server. This gives an end-to-end throughput estimate; PingMetric displays the result as download and upload speed. `),El()(),Ms(44,`section`,5)(45,`h2`),sw(46,`Latency, ping, jitter and RTT`),El(),Ms(47,`p`),sw(48,` Latency is the time a response takes, shown in milliseconds. Lower latency usually makes browsing, calls, games and remote apps feel more responsive. PingMetric shows the median of browser HTTP/application probes and TCP timing when the browser exposes it. `),El(),Ms(49,`p`)(50,`strong`),sw(51,`HTTP`),El(),sw(52,` (Hypertext Transfer Protocol) is the request-and-response format browsers use to load web resources. `),Ms(53,`strong`),sw(54,`HTTPS`),El(),sw(55,` is HTTP protected with encryption and server identity checks. PingMetric's latency probe uses a web request, so it measures the browser's application path rather than every part of the network stack. `),El(),Ms(56,`p`)(57,`strong`),sw(58,`RTT`),El(),sw(59,` means Round-Trip Time: the time for data to go from your device to a server and for a response to return. `),Ms(60,`strong`),sw(61,`MinRTT`),El(),sw(62,` is the minimum TCP round-trip time observed during a transfer; `),Ms(63,`strong`),sw(64,`RTTVar`),El(),sw(65,` is TCP's estimate of how much RTT varies. They help describe path delay and stability. NDT7 may include them in the TCP result stored with a test; PingMetric's current dashboard does not display them separately, and they are not the dashboard's HTTP latency sample. `),El(),Ms(66,`details`,6)(67,`summary`),sw(68,`Jitter`),El(),Ms(69,`p`),sw(70,` Jitter is latency variation. 20, 21, 19, 20 ms is stable; 20, 80, 25, 110 ms is not. PingMetric uses the average absolute difference between consecutive HTTP/application samples. It matters for VoIP, video, games, streaming and remote control. `),El()(),Ms(71,`details`)(72,`summary`),sw(73,`Loaded latency`),El(),Ms(74,`p`),sw(75,` Loaded latency is response time while a download or upload is using the connection. A large increase can indicate queues building in a modem, router, or network path. This is sometimes called `),Ms(76,`strong`),sw(77,`bufferbloat`),El(),sw(78,`: oversized queues add delay even though data is still moving. It matters for calls and games during downloads. PingMetric compares available latency measurements during the test; this is a clue, not a definitive bufferbloat diagnosis. `),El()(),Ms(79,`p`)(80,`strong`),sw(81,`ICMP`),El(),sw(82,` means Internet Control Message Protocol, a network-layer protocol used for diagnostics and error reports. Classic command-line ping usually sends ICMP Echo requests. Browsers do not let web pages send arbitrary ICMP packets, so PingMetric instead measures HTTP/application latency. The two tests can differ because they use different protocols and paths. `),El()(),Ms(83,`section`,7)(84,`h2`),sw(85,`TCP and retransmission`),El(),Ms(86,`p`)(87,`strong`),sw(88,`TCP`),El(),sw(89,` means Transmission Control Protocol. It delivers data in order and checks receipt, retransmitting data when needed. This reliability is important for web pages and downloads, but retransmissions and congestion can affect throughput. PingMetric uses TCP for the NDT7 transfer and reports its retransmission estimate as `),Ms(90,`code`),sw(91,`(bytesRetrans / bytesSent) × 100`),El(),sw(92,` when those fields exist. It is not exact packet loss; a higher value can reflect congestion, Wi-Fi interference, unstable paths or temporary loss. MinRTT and RTTVar, when present in TCP details, describe transfer timing rather than classic ICMP ping. `),El()(),Ms(93,`section`,8)(94,`h2`),sw(95,`IP, routing and dual stack`),El(),Ms(96,`p`)(97,`strong`),sw(98,`IP`),El(),sw(99,` means Internet Protocol. It gives devices addresses and carries packets between networks. PingMetric shows the public addresses its browser checks can reach; it cannot inspect every address inside your home or office network. `),El(),Ms(100,`p`)(101,`strong`),sw(102,`IPv4`),El(),sw(103,` is Internet Protocol version 4 and uses 32-bit addresses such as `),Ms(104,`code`),sw(105,`192.0.2.10`),El(),sw(106,`. `),Ms(107,`strong`),sw(108,`IPv6`),El(),sw(109,` is Internet Protocol version 6 and uses 128-bit addresses such as `),Ms(110,`code`),sw(111,`2001:db8::1234`),El(),sw(112,`. IPv6 provides a much larger address space. PingMetric reports whether IPv4, IPv6, or both (dual stack) are reachable from the browser. `),El(),Ms(113,`p`)(114,`strong`),sw(115,`NAT`),El(),sw(116,` (Network Address Translation) lets a router share one public address across devices using private addresses. `),Ms(117,`strong`),sw(118,`CGNAT`),El(),sw(119,` (Carrier-Grade NAT) is similar sharing performed by an Internet provider, sometimes for many customers. It can affect inbound connections and makes a public IP identify a shared gateway rather than one device. PingMetric sees the public-facing address, not the private addresses behind NAT. `),El(),Ms(120,`p`)(121,`strong`),sw(122,`ASN`),El(),sw(123,` means Autonomous System Number. It identifies a network that announces Internet routes, often an ISP or hosting provider; PingMetric shows it in network intelligence. `),Ms(124,`strong`),sw(125,`CIDR`),El(),sw(126,` means Classless Inter-Domain Routing. A range such as `),Ms(127,`code`),sw(128,`203.0.113.0/24`),El(),sw(129,` describes a group of addresses and appears as a route/network detail. `),Ms(130,`strong`),sw(131,`RIR`),El(),sw(132,` means Regional Internet Registry, the regional organization responsible for allocating address resources; PingMetric shows the provider-reported RIR when available. `),El(),Ms(133,`p`)(134,`strong`),sw(135,`Anycast`),El(),sw(136,` means the same IP address is announced from multiple locations, with routing directing traffic to one of them. It can improve reachability and response time; PingMetric may show it as an IP-intelligence classification. A `),Ms(137,`strong`),sw(138,`bogon`),El(),sw(139,` is an address range that should not normally appear on the public Internet. A `),Ms(140,`strong`),sw(141,`reserved address`),El(),sw(142,` is set aside for special uses, such as private networks or documentation, rather than ordinary public routing. PingMetric can show a bogon/reserved classification, but provider data can be incomplete or mistaken. `),El()(),Ms(143,`section`,9)(144,`h2`),sw(145,`WebRTC and privacy`),El(),Ms(146,`p`)(147,`strong`),sw(148,`WebRTC`),El(),sw(149,` means Web Real-Time Communication. It enables browser voice/video calls and direct data connections. PingMetric can run a bounded WebRTC check to show the network candidates the browser exposes; a candidate is not by itself proof of a privacy leak. `),El(),Ms(150,`p`)(151,`strong`),sw(152,`ICE`),El(),sw(153,` (Interactive Connectivity Establishment) is how WebRTC gathers and tries possible connection routes. A `),Ms(154,`strong`),sw(155,`host`),El(),sw(156,` candidate describes a local interface, `),Ms(157,`strong`),sw(158,`srflx`),El(),sw(159,` (server-reflexive) describes an address learned through a server, and `),Ms(160,`strong`),sw(161,`relay`),El(),sw(162,` uses a forwarding server. PingMetric labels the candidate types it can observe. `),El(),Ms(163,`p`)(164,`strong`),sw(165,`STUN`),El(),sw(166,` means Session Traversal Utilities for NAT; it helps a device learn how it appears outside its router. `),Ms(167,`strong`),sw(168,`TURN`),El(),sw(169,` means Traversal Using Relays around NAT; it forwards media when a direct route cannot be made. PingMetric's WebRTC test uses configured STUN servers and does not operate a TURN relay. `),El(),Ms(170,`p`)(171,`strong`),sw(172,`mDNS`),El(),sw(173,` means Multicast DNS. Browsers may replace a local address in a WebRTC host candidate with a temporary-looking `),Ms(174,`code`),sw(175,`.local`),El(),sw(176,` name to make the device's local address harder for a page to identify. PingMetric labels such candidates as mDNS rather than treating the name as a public IP. `),El()(),Ms(177,`section`,10)(178,`h2`),sw(179,`Network intelligence and browser APIs`),El(),Ms(180,`p`)(181,`strong`),sw(182,`VPN`),El(),sw(183,` means Virtual Private Network: traffic is sent through another network endpoint, often to protect traffic on the way to it. A `),Ms(184,`strong`),sw(185,`proxy`),El(),sw(186,` is an intermediary that makes requests or forwards traffic for a device. `),Ms(187,`strong`),sw(188,`Tor`),El(),sw(189,` (The Onion Router) routes traffic through multiple relays to make tracing its path harder. `),Ms(190,`strong`),sw(191,`Datacenter/hosting`),El(),sw(192,` means an address is associated with servers rather than a typical home connection. These are provider-reported IP classifications; PingMetric shows generic detected/not-detected states and can be wrong. They do not identify what software or service you personally use. `),El(),Ms(193,`p`),sw(194,` The `),Ms(195,`strong`),sw(196,`Network Information API`),El(),sw(197,` is an optional browser interface that may report an estimated connection type, downlink, and RTT. It matters as a rough local hint, not a measured line speed. PingMetric labels these as browser estimates and keeps them separate from NDT7 results. `),El(),Ms(198,`p`)(199,`strong`),sw(200,`Web Crypto`),El(),sw(201,` is the browser's cryptographic API for operations such as hashing. PingMetric checks whether it is available for app functions; its presence does not mean every website connection or device setting is secure. A `),Ms(202,`strong`),sw(203,`secure context`),El(),sw(204,` is a browser page loaded in a protected setting, usually HTTPS (with localhost as a development exception). Some browser APIs, including Web Crypto features, require one. PingMetric reports whether its current page has a secure context. `),El(),Ms(205,`p`)(206,`strong`),sw(207,`DNS`),El(),sw(208,` means Domain Name System; it looks up the address for a name such as a website domain. A `),Ms(209,`strong`),sw(210,`DNS leak`),El(),sw(211,` is when name lookups use a DNS provider or route different from the one a person expects, for example outside a VPN. Reliable detection needs controlled DNS servers and observation of the resolver receiving each lookup. A browser-only page cannot reliably see that path, so PingMetric marks DNS leak testing as unavailable rather than guessing. `),El()(),Ms(212,`section`)(213,`h2`),sw(214,`What should I avoid sharing?`),El(),Ms(215,`p`),sw(216,` Be cautious with screenshots containing full IPv4/IPv6, WebRTC addresses, coordinates, postal code, city plus network identity, ISP/ASN plus exact IP, or CIDR/route. Together, public routing details can make profiling easier. Speeds, latency, jitter, dual-stack status and generic browser support are generally less sensitive. Use “Hide sensitive info” before sharing; it visually hides details but is not encryption. `),El()()())},dependencies:[_v],styles:[`.page[_ngcontent-%COMP%]{max-width:52rem;margin:auto;padding:1.5rem 1rem 3rem;line-height:1.65}.page[_ngcontent-%COMP%]   section[_ngcontent-%COMP%]{margin:1rem 0;padding:1rem;border:1px solid var(--%NS%border);border-radius:.8rem;background:var(--%NS%surface)}h1[_ngcontent-%COMP%]{line-height:1.1}h2[_ngcontent-%COMP%]{display:flex;gap:.45rem;align-items:center;font-size:1.2rem}code[_ngcontent-%COMP%]{overflow-wrap:anywhere}.eyebrow[_ngcontent-%COMP%]{color:var(--%NS%muted);text-transform:uppercase;letter-spacing:.06em}`]})};export{o as NetworkGuideComponent};